export class SearchService {
    /**
     * Search Documents
     *
     * Full-text search over title + content (Postgres tsvector), scoped to readable documents.
     */
    public static searchDocuments<ThrowOnError extends boolean = true>(options: Options<searchSearchDocumentsData, ThrowOnError>) {
        return (options.client ?? client).get<searchSearchDocumentsResponses, searchSearchDocumentsErrors, ThrowOnError>({
            responseType: 'json',
            security: [{ scheme: 'bearer', type: 'http' }, { scheme: 'bearer', type: 'http' }],
            url: '/api/v1/search/',
            ...options
        });
    }
    
    /**
     * Retrieve Documents
     *
     * Hybrid search: BM25 and/or vector search over pages, summaries and chunks.
     *
     * Each enabled method runs against each enabled target as a separate ranked
     * source; the rankings are then fused with Reciprocal Rank Fusion, so a page
     * several sources agree on outranks one that only a single source likes.
     */
    public static retrieveDocuments<ThrowOnError extends boolean = true>(options: Options<searchRetrieveDocumentsData, ThrowOnError>) {
        return (options.client ?? client).get<searchRetrieveDocumentsResponses, searchRetrieveDocumentsErrors, ThrowOnError>({
            responseType: 'json',
            security: [{ scheme: 'bearer', type: 'http' }, { scheme: 'bearer', type: 'http' }],
            url: '/api/v1/search/retrieve',
            ...options
        });
    }
}

